int orbit_color_enabled(void) {
    static int cached = -1;
    if (cached < 0) {
        cached = 1;
        const char* no_color = getenv("NO_COLOR");
        if (no_color != NULL && no_color[0] != 0) cached = 0;
        const char* term = getenv("TERM");
        if (term != NULL && strcmp(term, "dumb") == 0) cached = 0;
    }
    return cached;
}

