void o_doctorPrintGates(OrbitArena* arena) {
    orbit_print_string("gates: doctor never runs these itself; run them from the repository root:");
    orbit_print_string("  python scripts/verify_seed.py --cc <gcc-or-clang> --emit-fixed-point <path-to-orbit>");
    orbit_print_string("  python scripts/parity_selfhost.py --cc <gcc-or-clang> --compiler <path-to-orbit>");
    orbit_print_string("  python scripts/test_suite.py --cc <gcc-or-clang> --compiler <path-to-orbit>");
    return;
}

void o_doctorPrintHelp(OrbitArena* arena) {
    orbit_print_string("Usage: orbit doctor [dir] [options]");
    orbit_print_string("");
    orbit_print_string("Scans .orb files under [dir] (default: the current directory) without changing them.");
    orbit_print_string("  --fix           Apply the fixes doctor knows how to make.");
    orbit_print_string("  --unsafe        Also apply the structural fixes; off by default.");
    orbit_print_string("  --verify-build  Check each fixed file compiles to C (on by default with --fix).");
    orbit_print_string("  --fast          Skip that C check; the front end is still checked.");
    orbit_print_string("  --dry-run       Report what --fix would change, and change nothing.");
    orbit_print_string("  --only CODES    Only these codes, e.g. --only D006,D007.");
    orbit_print_string("  --skip CODES    Every code but these.");
    orbit_print_string("  --min-severity warning|error  Hide anything below this severity.");
    orbit_print_string("  --baseline FILE Print findings listed in FILE but do not fail on them.");
    orbit_print_string("  --telemetry FILE A ledger snapshot to check routes against; defaults to");
    orbit_print_string("                  $ORBIT_LEDGER_OUT. Absent, D031-D033 stay silent.");
    orbit_print_string("  --budget-doc FILE  The ENGINEERING.md whose latency budget D033 enforces;");
    orbit_print_string("                      defaults to ./ENGINEERING.md.");
    orbit_print_string("  --quiet         Findings (and fixes) only; no summaries or gate list.");
    orbit_print_string("  --verbose       Also print the scan scope, the per-phase timings, and the gate list.");
    orbit_print_string("  --format text|json  Output format; json is a JSON array on stdout.");
    orbit_print_string("  --color always|never|auto  ANSI colors (auto honors NO_COLOR/TERM).");
    orbit_print_string("");
    orbit_print_string("Exit codes: 0 clean, 1 findings, 2 usage.");
    return;
}

void o_doctorUsage(OrbitArena* arena) {
    orbit_os_write_stderr_selfhost((orbit_string)("Usage: orbit doctor [dir] [options]\nRun `orbit doctor --help` for details.\n"));
    return;
}

