void o_clusterUsage(OrbitArena* arena) {
    orbit_print_string("Usage: orbit cluster <command> [options]");
    orbit_print_string("");
    orbit_print_string("Commands:");
    orbit_print_string("  up --nodes N --port-base P [--log-dir D] [--service S]");
    orbit_print_string("                           Compile the service once, launch N nodes on ports P..P+N-1");
    orbit_print_string("  status                   Per-node health (alive/dead, draining flag)");
    orbit_print_string("  drain <node>             Graceful stop of one node (finish in-flight, no restart)");
    orbit_print_string("  restart --rolling        One node at a time, health-verified before the next");
    orbit_print_string("  down                     Stop all nodes, remove state (no orphans left)");
    orbit_print_string("  logs <node>              Print a node's log file");
    orbit_print_string("  --quiet                  Only errors (status, logs and findings still print)");
    orbit_print_string("  --verbose                Also echo spawned commands and scan totals");
    orbit_print_string("");
    orbit_print_string("Single host only. See docs/CLUSTER.md.");
    return;
}

